head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vMktactCd = '305'; // 채권시장조치구분코드
scwin.pBndApplId = '';
scwin.vBndListProcsTpCd = 1; // 채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.vViewYN = 'Y';
scwin.vIsuCd = '';
scwin.arrPar = new Array();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vStripAmtCfm, scwin.vRegYn = '';

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.bns.BnsPanelToGroupBox(pnl_Req); // 패널라운드처리(신청)
        $c.bns.BnsPanelToGroupBox(pnl_DtlInfo); // 패널라운드처리(상세)
        $c.bns.BnsPanelToGroupBox(pnl_Acpt); // 패널라운드처리(접수)

        tab_List.setSelectedTabIndex(1);
        scwin.setParam(); // 호출파라미터설정
        scwin.dtlSync(); // 상세조회
        // 필드 ReadOnly 속성 제거/부여
        scwin.chgTabAct(scwin.vBndListProcsTpCd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90012.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tab_List_OnSelChanged
 * @description tab List On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.tab_List_OnSelChanged = function(nIndex) {
    try {
        scwin.vBndListProcsTpCd = nIndex;
        scwin.dtlSync(); // 상세조회
        // 필드 ReadOnly 속성 제거/부여
        scwin.chgTabAct(scwin.vBndListProcsTpCd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90012.tab_List_OnSelChanged" });
    }
};

/**
 * @method
 * @name dts_DtlInfo_OnLoadCompleted
 * @description dts_DtlInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    try {
        scwin.vDtlInfoRowCount = rowcount;

        // 당일 스트립 체크 설정
        if (dts_DtlInfo.getCellData(1, "TDD_STRIP_MKTACT_YN") === 'Y') {
            chk_Tdd_StripMktactYn.setValue(1);
        } else {
            chk_Tdd_StripMktactYn.setValue(0);
        }
        scwin.vIsuCd = dts_DtlInfo.getCellData(1, "ISU_CD");
        scwin.addPubSync(); // 추가발행내역 조회

        edt_CoupnRt.RightMargin = 5;
        edt_IsuAmt.RightMargin = 5;
        edt_ListAmt.RightMargin = 5;
        edt_BfchgStripNsprtBal.RightMargin = 5;
        edt_AddCoupnRt.RightMargin = 5;
        edt_TotIsuAmt.RightMargin = 5;
        edt_TotListAmt.RightMargin = 5;
        edt_AfchgStripNsprtBal.RightMargin = 5;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90012.dts_DtlInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_StrtDd_onclick
 * @description img_StrtDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_StrtDd_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        popUpCalendar2(edt_StrtDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90012.img_StrtDd_onclick" });
    }
};

/**
 * @method
 * @name img_AddIsuDd_onclick
 * @description img_AddIsuDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_AddIsuDd_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        popUpCalendar2(edt_AddIsuDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90012.img_AddIsuDd_onclick" });
    }
};

/**
 * @method
 * @name btn_Attach_onclick
 * @description 「첨부파일확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Attach_onclick = async function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        if ("N" === dts_DtlInfo.getCellData(dts_DtlInfo.getRowPosition(), "HAS_ATTACH_DOC")) {
            await $c.win.alert("연결된 팩스/첨부문서가 없습니다.");
            return;
        }
        scwin.fn_GetPar = scwin.getCommonKey;
        $c.bns.fn_PopAttachDocSearch(lbl_BndApplId);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90012.btn_Attach_onclick" });
    }
};

/**
 * @method
 * @name btn_Dtl_onclick
 * @description 「종목상세내역」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Dtl_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.fn_GetPar = scwin.getParIsuDelInfo;
        $c.bns.fn_PopIsuDetail(lbl_BndApplId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90012.btn_Dtl_onclick" });
    }
};

/**
 * @method
 * @name img_StripAmtCfm_onclick
 * @description img_StripAmtCfm 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_StripAmtCfm_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        if (chk_Tdd_StripMktactYn.checked === true) {
            scwin.vStripAmtCfm = "View";
            scwin.fn_GetPar = scwin.getAddAndStripMktactAmtCfm;
            scwin.fn_SetPar = scwin.setRegYnReturn;
            $c.bns.fn_PopAddAndStripMktactAmtCfm(lbl_BndApplId);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90012.img_StripAmtCfm_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS90012.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name edt_CoupnRt_OnKillFocus
 * @description edt_CoupnRt 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.edt_CoupnRt_OnKillFocus = function() {
    try {
        edt_CoupnRt.RightMargin = 5;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90012.edt_CoupnRt_OnKillFocus" });
    }
};

