/**
 * @method
 * @name dts_DtlInfo_OnColumnChanged
 * @description Dtl Info On Column Changed 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.dts_DtlInfo_OnColumnChanged = function(row, colid) {
    try {
        if (colid === "ADD_ISU_AMT") {
            /** 추가발행금액(화면 자동 계산) */
            if (scwin.vBndListProcsTpCd = 2) {
                edt_TotIsuAmt.setValue(Number(edt_IsuAmt.getValue()) + Number(edt_AddIsuAmt.getValue()));
                edt_TotListAmt.setValue(Number(edt_ListAmt.getValue()) + Number(edt_AddIsuAmt.getValue()));
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS90012.dts_DtlInfo_OnColumnChanged" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        scwin.fn_GetPar(scwin.arrPar);
        scwin.pBndApplId = scwin.arrPar[0].BND_APPL_ID;
    }
};

/**
 * @method
 * @name dtlSync
 * @description 상세조회
 * @returns {void}
 * @hidden N
 */
scwin.dtlSync = function() {
    let dsNm = 'BNS_ISU_CHG_INFO';
    let qryId = 'lds.stf.bnsisuchg.select.readIsuChgInfoAmtMmDdAdd';
    let param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    param += '&{P}V_BND_APPL_ID=' + scwin.pBndApplId;
    param += '&{P}V_VIEW_YN=' + scwin.vViewYN;
    $c.bns.fn_SearchBns('ULDBNS90012.xml', dts_DtlInfo, dsNm, qryId, param);
};

/**
 * @method
 * @name addPubSync
 * @description 추가발행내역 조회
 * @returns {void}
 * @hidden N
 */
scwin.addPubSync = function() {
    let dsNm = 'BNS_ADD_PUB_DESC';
    let qryId = 'lds.stf.bnsisuchg.select.listAddPubDesc';
    let param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_ISU_CD=' + scwin.vIsuCd;
    $c.bns.fn_SearchBns('ULDBNS90012.xml', dts_AddHistory, dsNm, qryId, param);
};

/**
 * @method
 * @name getCommonKey
 * @description 팝업에 넘길 키데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getCommonKey = function(arrPar) {
    scwin.arrPar[0] = {
        // 첨부문서 목록 팝업
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISU_CD: dts_DtlInfo.getCellData(1, "ISU_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name getParIsuDelInfo
 * @description 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuDelInfo = function(arrPar) {
    scwin.arrPar[0] = {
        STD_CD: dts_DtlInfo.getCellData(1, "ISU_CD"),
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name getAddAndStripMktactAmtCfm
 * @description 추가상장/스트립 동시 시장조치 금액확인 팝업에 넘길 데이터를 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getAddAndStripMktactAmtCfm = function(arrPar) {
    scwin.arrPar[0] = {
        VIEW_YN: scwin.vStripAmtCfm,
        BND_MKTACT_TP_CD: scwin.vMktactCd,
        ISU_CD: dts_DtlInfo.getCellData(1, "ISU_CD"),
        BND_APPL_ID: dts_DtlInfo.getCellData(1, "BND_APPL_ID"),
        ADD_ISU_AMT: dts_DtlInfo.getCellData(1, "ADD_ISU_AMT"),
        BND_LIST_PROCS_TP_CD: dts_DtlInfo.getCellData(1, "BND_LIST_PROCS_TP_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name setRegYnReturn
 * @description 추가상장/스트립 동시 시장조치 금액확인 팝업에서 받은 데이터를 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setRegYnReturn = function(arrPar) {
    scwin.vRegYn = scwin.arrPar[0].REG_YN;
};

/**
 * @method
 * @name chgTabAct
 * @description 필드 ReadOnly 속성 제거/부여
 * @param {String} vBndListProcsTpCd vBndListProcsTpCd
 * @returns {void}
 * @hidden N
 */
scwin.chgTabAct = function(vBndListProcsTpCd) {
    // 낙찰금리, 추가발행일, 추가발행금액
    if (scwin.vBndListProcsTpCd === 1) {
        edt_AddCoupnRt.setReadOnly("true");
        edt_AddIsuDd.setReadOnly("true");
        img_AddIsuDd.hide(); // 추가발행일 달력
        edt_AddIsuAmt.setReadOnly("true");
    } else if (scwin.vBndListProcsTpCd === 2) {
        edt_AddCoupnRt.setReadOnly("false");
        edt_AddIsuDd.setReadOnly("false");
        img_AddIsuDd.show(""); // 추가발행일 달력
        edt_AddIsuAmt.setReadOnly("false");
    }
};
